<script setup lang="ts">
const { data: metrics, status, error, refresh } = await useFetch<any>("/api/provider/metrics")
const tenantId=ref("");const tenantMetrics=ref<any>();const tenantError=ref("")
async function inspectTenant(){tenantError.value="";tenantMetrics.value=undefined;if(!tenantId.value.trim())return;try{tenantMetrics.value=await $fetch(`/api/provider/metrics/tenant/${encodeURIComponent(tenantId.value.trim())}`)}catch(e:any){tenantError.value=e?.data?.message??e?.statusMessage??e?.message??"Tenant metrics lookup failed."}}
</script>
<template><div class="page-stack"><div class="page-heading"><div><p class="eyebrow">PLATFORM</p><h1>IAM Metrics</h1><p>Canonical operational metrics derived by Saiwaly IAM™.</p></div><button class="secondary-button" @click="()=>refresh()">Refresh</button></div><div v-if="status==='pending'" class="panel loading-panel">Loading IAM metrics…</div><div v-else-if="error" class="panel error-panel"><strong>Metrics unavailable</strong><p>{{error.statusMessage}}</p></div><template v-else-if="metrics"><section class="metric-grid"><article class="metric-card"><span>Identities</span><strong>{{metrics.identities.total}}</strong><small>{{metrics.identities.active}} active · {{metrics.identities.suspended}} suspended</small></article><article class="metric-card"><span>Active sessions</span><strong>{{metrics.sessions.active}}</strong><small>{{metrics.authentication.lifecycleEvents}} authentication lifecycle events</small></article><article class="metric-card"><span>Memberships</span><strong>{{metrics.memberships.active}}</strong><small>{{metrics.memberships.total}} total · {{metrics.invitations.pending}} pending invitations</small></article><article class="metric-card"><span>Access assignments</span><strong>{{metrics.authorization.activeRoleAssignments+metrics.authorization.activeDirectAssignments}}</strong><small>{{metrics.authorization.activeRoleAssignments}} role · {{metrics.authorization.activeDirectAssignments}} direct</small></article></section><section class="two-column"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">AUTHORIZATION</p><h2>Canonical signals</h2></div></div><div class="signal-grid"><div><span>Access lifecycle events</span><strong>{{metrics.authorization.accessLifecycleEvents}}</strong></div><div><span>Denials</span><strong>{{metrics.authorization.denials}}</strong></div></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">PROCESSING</p><h2>Recorded failures</h2></div></div><div class="signal-grid"><div><span>Processing failures</span><strong>{{metrics.processing.failures}}</strong></div></div><p class="muted compact">These are IAM-owned counts. Provider Admin does not infer additional health semantics.</p></article></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">TENANT METRICS</p><h2>Inspect tenant scope</h2></div></div><div class="admin-filters"><input v-model="tenantId" placeholder="Tenant ID" @keyup.enter="inspectTenant"><button class="secondary-button" @click="inspectTenant">Inspect</button></div><div v-if="tenantError" class="alert alert--error">{{tenantError}}</div><template v-if="tenantMetrics"><div class="result-meta"><span>Tenant <strong class="mono">{{tenantMetrics.scope.tenantId}}</strong></span><span>Scope <strong>Tenant</strong></span></div><section class="metric-grid"><article class="metric-card"><span>Identities</span><strong>{{tenantMetrics.identities.total}}</strong><small>{{tenantMetrics.identities.active}} active · {{tenantMetrics.identities.suspended}} suspended</small></article><article class="metric-card"><span>Active sessions</span><strong>{{tenantMetrics.sessions.active}}</strong><small>{{tenantMetrics.authentication.lifecycleEvents}} authentication lifecycle events</small></article><article class="metric-card"><span>Memberships</span><strong>{{tenantMetrics.memberships.active}}</strong><small>{{tenantMetrics.memberships.total}} total · {{tenantMetrics.invitations.pending}} pending invitations</small></article><article class="metric-card"><span>Access assignments</span><strong>{{tenantMetrics.authorization.activeRoleAssignments+tenantMetrics.authorization.activeDirectAssignments}}</strong><small>{{tenantMetrics.authorization.activeRoleAssignments}} role · {{tenantMetrics.authorization.activeDirectAssignments}} direct</small></article></section><div class="two-column"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">AUTHORIZATION</p><h2>Tenant signals</h2></div></div><div class="signal-grid"><div><span>Access lifecycle events</span><strong>{{tenantMetrics.authorization.accessLifecycleEvents}}</strong></div><div><span>Denials</span><strong>{{tenantMetrics.authorization.denials}}</strong></div></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">PROCESSING</p><h2>Tenant failures</h2></div></div><div class="signal-grid"><div><span>Processing failures</span><strong>{{tenantMetrics.processing.failures}}</strong></div></div><p class="muted compact">Canonical IAM-owned tenant counts.</p></article></div></template></section></template></div></template>
